/**
 * BarChart
 *
 * Decorative animated bars growing from bottom with staggered spring,
 * accent gradient. Used as a chart-led background; the actual content
 * sits above in TemplateText.
 */

import { interpolate, spring, SPRING_SNAPPY } from "../../react-animations/animation-utils";

// ─── Typed component (direct use from templates) ────────────────

export interface BarChartProps {
  progress: number;
  /** Bar values 0-100 */
  barValues: number[];
  width: number;
  height: number;
  beatIntensity?: number;
}

export const BarChart: React.FC<BarChartProps> = ({
  progress,
  barValues,
  width,
  height,
  beatIntensity = 0,
}) => {
  const s = Math.min(width, height) / 1080;
  const barCount = barValues.length || 1;
  const maxBarHeight = height * 0.6;
  const chartWidth = width * 0.85;
  const gap = 8 * s;
  const barWidth = (chartWidth - gap * (barCount - 1)) / barCount;
  const beatScale = 1 + beatIntensity * 0.03;

  return (
    <>
      {/* Bars */}
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: (width - chartWidth) / 2,
          width: chartWidth,
          height: maxBarHeight,
          display: "flex",
          alignItems: "flex-end",
          gap,
        }}
      >
        {barValues.map((val, i) => {
          const barStart = 0.05 + i * 0.08;
          const barProgress = interpolate(progress, [barStart, barStart + 0.4], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const springVal = spring(barProgress, SPRING_SNAPPY);
          const targetHeight = (val / 100) * maxBarHeight;

          return (
            <div
              key={i}
              style={{
                width: barWidth,
                height: springVal * targetHeight,
                background: `linear-gradient(to top, rgba(255,255,255,0.35), rgba(255,255,255,0.15))`,
                border: "1px solid rgba(255,255,255,0.25)",
                borderRadius: `${8 * s}px ${8 * s}px 0 0`,
                transform: `scaleY(${beatScale})`,
                transformOrigin: "bottom",
              }}
            />
          );
        })}
      </div>

      {/* Subtle glow behind bars */}
      <div
        style={{
          position: "absolute",
          bottom: 0,
          left: 0,
          right: 0,
          height: maxBarHeight * 0.7,
          background: `linear-gradient(to top, rgba(255,255,255,0.05), transparent)`,
          pointerEvents: "none",
        }}
      />
    </>
  );
};
